DROP TABLE cereal_list;
CREATE TABLE cereal_list (cereal_id int NOT NULL AUTO_INCREMENT, name varchar(300), PRIMARY KEY (cereal_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE choices;
CREATE TABLE choices (chioce_id int NOT NULL AUTO_INCREMENT, name varchar(255), value varchar(255), elements_id int NOT NULL, PRIMARY KEY (chioce_id), INDEX elements_id_idx (elements_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE columns;
CREATE TABLE columns (column_id int NOT NULL AUTO_INCREMENT, name varchar(255), value varchar(255), elements_id int NOT NULL, PRIMARY KEY (column_id), INDEX columns_elements_id_fk (elements_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE count;
CREATE TABLE count (count_id int NOT NULL, name int NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE elements;
