DROP TABLE medicine_list;
CREATE TABLE medicine_list (medicine_id int NOT NULL AUTO_INCREMENT, name varchar(300), PRIMARY KEY (medicine_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE pages;
CREATE TABLE pages (page_id int NOT NULL AUTO_INCREMENT, name varchar(255) NOT NULL, title varchar(255), questionnaires_id int NOT NULL, PRIMARY KEY (name, questionnaires_id), INDEX questionnaires_id_idx (questionnaires_id), INDEX page_id (page_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE participant_email;
CREATE TABLE participant_email (participant_email_id int NOT NULL AUTO_INCREMENT, participant_id int NOT NULL, email varchar(255), PRIMARY KEY (participant_email_id), INDEX participantemail_fk1 (participant_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE participant_study;
CREATE TABLE participant_study (participant_study_id int NOT NULL AUTO_INCREMENT, participant_id int NOT NULL, study_information longtext, timeline varchar(255), study_id int, status varchar(255), completed_time timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NULL, access varchar(255), quid varchar(255), PRIMARY KEY (participant_study_id), INDEX participant_study_FK_1 (study_id), INDEX participant_study_FK_2 (participant_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE participants;
CREATE TABLE participants (projectid varchar(9), id int NOT NULL AUTO_INCREMENT, autotime timestamp DEFAULT CURRENT_TIMESTAMP, logid varchar(100) NOT NULL, loghost varchar(100), firstName varchar(25) NOT NULL, lastName varchar(25) NOT NULL, patientID varchar(25) NOT NULL, siteID varchar(2), naccID varchar(25), gender varchar(7) NOT NULL, race varchar(50) NOT NULL, ethnicity varchar(30) NOT NULL, dob varchar(7) NOT NULL, ques1 varchar(12) NOT NULL, ques2 varchar(12) NOT NULL, ques3 varchar(12) NOT NULL, ques4 varchar(12) NOT NULL, ques5 varchar(12), ques6 varchar(12), autolog timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, revlogid varchar(100), revloghost varchar(100), PRIMARY KEY (id), CONSTRAINT U_ProjectID UNIQUE (projectid), CONSTRAINT U_Paticipant UNIQUE (patientID, siteID)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE questionnaire_triggers;
CREATE TABLE questionnaire_triggers (questionnaire_trigger_id int NOT NULL AUTO_INCREMENT, expression varchar(255) NOT NULL, set_to_name varchar(255), set_value varchar(255), type varchar(255), questionnaires_id int NOT NULL, PRIMARY KEY (questionnaire_trigger_id), INDEX questionnaires_id_idx (questionnaires_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE questionnaires;
CREATE TABLE questionnaires (questionnaires_id int NOT NULL AUTO_INCREMENT, show_progress_bar varchar(45), show_page_titles tinyint, show_question_numbers varchar(45), completed_html blob, title varchar(500), show_preview_before_complete varchar(255), check_errors_mode varchar(255), study_id int NOT NULL, PRIMARY KEY (questionnaires_id), INDEX study_idx1 (study_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE rows;
CREATE TABLE rows (row_id int NOT NULL AUTO_INCREMENT, name varchar(255), value varchar(255), elements_id int NOT NULL, PRIMARY KEY (row_id), INDEX rows_elements_id_fk (elements_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE site;
CREATE TABLE site (site_id int NOT NULL, site varchar(25) NOT NULL, site_name varchar(255) NOT NULL, nacc_id int NOT NULL, PRIMARY KEY (site_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE study;
CREATE TABLE study (study_id int NOT NULL, study_name varchar(255), PRIMARY KEY (study_id)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE webroles;
CREATE TABLE webroles (username varchar(100) NOT NULL, rolename varchar(20) NOT NULL, PRIMARY KEY (username, rolename)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
DROP TABLE webusers;
CREATE TABLE webusers (sitename varchar(50), siteID varchar(3) NOT NULL, name varchar(200), username varchar(100) NOT NULL, email varchar(200), title varchar(3), active varchar(3), password varchar(10), userpass varchar(200), PRIMARY KEY (username)) ENGINE=InnoDB DEFAULT CHARSET=latin1 DEFAULT COLLATE=latin1_swedish_ci;
ALTER TABLE `choices` ADD CONSTRAINT elements_id FOREIGN KEY (`elements_id`) REFERENCES `elements` (`elements_id`) ON DELETE NO ACTION;
ALTER TABLE `columns` ADD CONSTRAINT columns_elements_id_fk FOREIGN KEY (`elements_id`) REFERENCES `elements` (`elements_id`) ON DELETE NO ACTION;
ALTER TABLE `elements` ADD CONSTRAINT elements_fk2 FOREIGN KEY (`questionnaires_id`) REFERENCES `questionnaires` (`questionnaires_id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `elements` ADD CONSTRAINT page_id_fk FOREIGN KEY (`page_id`) REFERENCES `pages` (`page_id`) ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE `pages` ADD CONSTRAINT questionnaires_id FOREIGN KEY (`questionnaires_id`) REFERENCES `questionnaires` (`questionnaires_id`);
ALTER TABLE `participant_email` ADD CONSTRAINT participantemail_fk1 FOREIGN KEY (`participant_id`) REFERENCES `participants` (`id`);
ALTER TABLE `questionnaire_triggers` ADD CONSTRAINT questionnaires_id_trigger FOREIGN KEY (`questionnaires_id`) REFERENCES `questionnaires` (`questionnaires_id`);
ALTER TABLE `questionnaires` ADD CONSTRAINT questionnaires_fk1 FOREIGN KEY (`study_id`) REFERENCES `study` (`study_id`);
ALTER TABLE `rows` ADD CONSTRAINT rows_elements_id_fk FOREIGN KEY (`elements_id`) REFERENCES `elements` (`elements_id`) ON DELETE NO ACTION;
